/**
 * Rebuild the Origin API handle (`ctx.origin`) for inbound hooks.
 *
 * The handle is repo-bound and lazy: no credential is resolved until the
 * first call, so channels without outbound Origin credentials still dispatch
 * normally. Credential resolution combines the channel's `app` option with
 * the environment (`ORIGIN_APP_ID` / `ORIGIN_APP_INSTALLATION_ID` /
 * `ORIGIN_APP_PRIVATE_KEY`); the delivery's installation id fills in when
 * neither pins one — the GitHub webhook `installation.id` analogue.
 */
import { createOriginClient, originRpcBaseUrl, resolveOriginAppCredentialParts, } from "./api.js";
import { createOriginCheck } from "./checks.js";
import { setOriginCommentReaction } from "./reactions.js";
export function buildOriginBinding(input) {
    const buildClient = (apiBaseUrl) => {
        const fromEnv = input.cursorAccount ? {} : resolveOriginAppCredentialParts();
        const appId = input.app?.appId ?? fromEnv.appId;
        const installationId = input.app?.installationId ?? input.installationId ?? fromEnv.installationId;
        const privateKey = input.app?.privateKey ?? fromEnv.privateKey;
        const credentials = appId !== undefined && installationId !== undefined && privateKey !== undefined
            ? { appId, installationId, privateKey }
            : undefined;
        return createOriginClient({
            token: input.cursorAccount ? undefined : input.app?.token,
            credentials: input.cursorAccount ? false : credentials,
            apiBaseUrl,
            fetch: input.fetch,
        });
    };
    // Public REST and ConnectRPC are separate Origin deployments, so the
    // handle keeps a client per host. Both stay lazy: a hook that touches
    // neither needs no credential.
    let restClient;
    const getRestClient = () => {
        restClient ??= buildClient(input.app?.apiBaseUrl);
        return restClient;
    };
    let rpcClient;
    const getRpcClient = () => {
        rpcClient ??= buildClient(input.app?.rpcBaseUrl ?? originRpcBaseUrl());
        return rpcClient;
    };
    return {
        installationId: input.app?.installationId ?? input.installationId,
        repository: input.repository,
        request: (request) => getRestClient().request(request),
        createCheck: (check) => createOriginCheck({
            ...check,
            executionId: check.executionId ?? input.executionId,
            origin: getRestClient(),
            owner: input.repository.owner,
            repo: input.repository.name,
        }),
        reactToComment: (reaction) => setOriginCommentReaction({ ...reaction, origin: getRpcClient() }),
    };
}
